SELECT id, approval_id, incident_code, action_command, proposed_by, approved_by, decision, created_at, decided_at
FROM remediation_approvals
WHERE approval_id = #{approvalId}

SELECT id, approval_id, incident_code, action_command, executed_by, execution_status, execution_output, executed_at
FROM remediation_executions
WHERE approval_id = #{approvalId}
